SELECT CASE WHEN c.country IN ('JP', 'SG') THEN 'core' ELSE 'other' END country_group, CASE WHEN YEAR(c.signup_date) < 2024 THEN 'before_2024' WHEN YEAR(c.signup_date) = 2024 THEN '2024' ELSE 'after_2024' END signup_cohort, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(o.channel))) channel_values, MIN(o.order_date) min_order_date FROM orders o LEFT JOIN customers c ON o.customer_id = c.id GROUP BY CASE WHEN c.country IN ('JP', 'SG') THEN 'core' ELSE 'other' END, CASE WHEN YEAR(c.signup_date) < 2024 THEN 'before_2024' WHEN YEAR(c.signup_date) = 2024 THEN '2024' ELSE 'after_2024' END;
